import requests, json

# Search for statsmodels BioContainer
url = "https://quay.io/api/v1/repository"
params = {"namespace": "biocontainers", "name": "statsmodels", "includeTags": "true"}
r = requests.get(f"{url}?namespace=biocontainers&name=statsmodels", params={"includeTags": "true"})
if r.status_code == 200:
    data = r.json()
    tags = data.get("tags", {})
    print("tags count:", len(tags))
    for tag_name in sorted(tags.keys(), reverse=True)[:10]:
        tag_data = tags[tag_name]
        print(f"  {tag_name}: {tag_data.get('manifest_digest', '?')}")
else:
    print(f"Status {r.status_code}: {r.text[:500]}")

# Also check pandas+statsmodels combined containers
for name in ["python", "pandas"]:
    params = {"namespace": "biocontainers", "name": name, "includeTags": "true"}
    r = requests.get(f"{url}?namespace=biocontainers&name={name}", params={"includeTags": "true"})
    if r.status_code == 200:
        data = r.json()
        tags = data.get("tags", {})
        print(f"\n{name}: {len(tags)} tags")
        for tag_name in sorted(tags.keys(), reverse=True)[:5]:
            print(f"  {tag_name}")
    else:
        print(f"\n{name}: Status {r.status_code}")

PYEOF

